const refresh = async (req: Request, res: Response): Promise<void> => {
    const oldToken = (req.cookies as Record<string, string>)["rt"];
    if (!oldToken) {
      res.status(401).json({ error: "No refresh token" });
      return;
    }
    try {
      const { access, refresh: newRefresh } = await tokenService.rotate(oldToken);
      res.cookie("rt", newRefresh, {
        httpOnly: true,
        sameSite: "strict",
        maxAge: REFRESH_TOKEN_TTL_DAYS * 24 * 60 * 60 * 1000,
      });
      res.json({ accessToken: access });
    } catch (err) {
      if (err instanceof InvalidToken || err instanceof TokenReuseDetected) {
        res.clearCookie("rt");
        res.status(401).json({ error: "Unauthorized" });
        return;
      }
      throw err;
    }
  };

export const ACCESS_TOKEN_TTL = 15 * 60; // seconds
export const REFRESH_TOKEN_TTL_DAYS = 30;
export const JWT_SECRET = process.env.JWT_SECRET ?? "dev-only-secret";

describe("refresh rotation", () => {
  it("refresh rotates token and old token yields 401", async () => {
    const { app } = setup();
    const loginRes = await request(app)
      .post("/auth/login")
      .send({ email: "alice@shoply.test", password: "demo1234" });
    const cookies = loginRes.headers["set-cookie"] as string[];
    const rtCookie = cookies.find((c: string) => c.startsWith("rt="));
    expect(rtCookie).toBeDefined();

    const refreshRes = await request(app)
      .post("/auth/refresh")
      .set("Cookie", rtCookie!);
    expect(refreshRes.status).toBe(200);
    expect(refreshRes.body).toHaveProperty("accessToken");

    const reuseRes = await request(app)
      .post("/auth/refresh")
      .set("Cookie", rtCookie!);
    expect(reuseRes.status).toBe(401);
  });
})

const findByHash = (hash: string): RefreshTokenRow | undefined => {
    return db
      .prepare<[string], RefreshTokenRow>(
        "SELECT * FROM refresh_tokens WHERE token_hash = ?"
      )
      .get(hash);
  };
